update app.business_rule_catalog set status='active',source='approved_v2',enforcement='command',test_status='tested',source_ref='Decision 2026-08-19',description='Academy monthly fees are separate canonical receivable charges. The first active month is prorated with the organization billing proration method; the standard due day applies; first-month late-fee policy follows billing policy, and subsequent unpaid academy fees accrue the standard late fee.',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('decisionDate','2026-08-19','qa','rollback_pass','separateLedgerCharge',true),updated_at=now() where rule_key='ACA-BILL-001';
update app.business_rule_catalog set status='active',source='approved_v2',enforcement='command',test_status='tested',source_ref='Decision 2026-08-19',description='Sponsor-funded player fees such as Curtibrother are configurable per player as a fixed amount or percentage of the contracted monthly total. Canonical charges split sponsor vs family responsibility, and payments only allocate to matching responsibility so sponsor and family receivables cannot be mixed.',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('decisionDate','2026-08-19','qa','rollback_pass','configurable',true,'payerIsolation',true),updated_at=now() where rule_key='BENEFIT-SPONSOR-001';
update app.business_rule_catalog set status='active',source='approved_v2',enforcement='command',test_status='tested',source_ref='Decision 2026-08-19',description='Only Presidencia can authorize new waivers, discounts, or downward debt corrections. Accounting may post an approved authorization. Amount, reason, authorization actor/time, posting actor/time and the original charge are preserved; debt is adjusted, never deleted.',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('decisionDate','2026-08-19','qa','rollback_pass','authorizationRole','Presidencia','postingRole','Contabilidad'),updated_at=now() where rule_key='BILL-WAIVER-001';
update app.business_rule_catalog set status='active',source='approved_v2',enforcement='command',test_status='tested',source_ref='Decision 2026-08-19',description='Commerce creates the production batch and freezes sale and cost snapshots. Accounting records supplier payments linked to the batch and may not pay above the frozen payable. Financial reporting preserves who paid each order, supplier payments, expected gross profit and current net cash separately.',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('decisionDate','2026-08-19','qa','rollback_pass','commerceCreatesBatch',true,'accountingPaysSupplier',true,'payerAttribution',true),updated_at=now() where rule_key='CUT-PAY-001';;
